<template>
  <v-card variant="outlined" class="pa-4 mb-4">
    <div class="manual-heading"><span class="manual-icon"><v-icon size="22">mdi-message-text-outline</v-icon></span><div><h2>Phân tích hội thoại</h2><p>Chọn hội thoại, xem trước và xác nhận phân tích. Chứng cứ được lưu 7 ngày.</p></div></div>
    <v-alert v-if="error" type="error" class="mb-3">{{ error }}</v-alert>
    <v-alert v-if="retentionDays!==7" type="warning" class="mb-3">Cần cấu hình thời gian lưu chứng cứ 7 ngày trước khi gửi.</v-alert>
    <v-btn v-if="permissions.includes('edit') && permissions.includes('approve') && retentionDays!==7" :disabled="busy" @click="setRetention">Đặt thời gian lưu 7 ngày</v-btn>
    <v-btn class="ma-2" variant="outlined" :disabled="busy" @click="loadConversations">Tải danh sách hội thoại</v-btn>
    <v-select v-model="conversationId" :items="conversations" item-title="title" item-value="id" :item-props="conversationProps" label="Chọn hội thoại" no-data-text="Bấm “Tải danh sách hội thoại”" :disabled="busy" />
    <v-select v-model="messageLimit" :items="[10,20,50]" label="Số tin nhắn gần nhất" :disabled="busy" />
    <v-textarea v-model="redactionsText" label="Thông tin cần ẩn thêm, mỗi dòng một mục" hint="Nhập tên, địa chỉ hoặc thông tin riêng cần che. Luôn kiểm tra bản xem trước." persistent-hint :disabled="busy" />
    <v-btn :disabled="busy || !conversationId || !canCreate" @click="preview">Xem trước bản gửi</v-btn>
    <template v-if="previewData">
      <div class="manual-preview-meta"><v-chip size="small" variant="tonal">{{ previewData.knowledge.length }} quy tắc liên quan</v-chip><span>Bản xem trước có hiệu lực 5 phút</span></div>
      <div v-for="m in previewData.conversation.messages" :key="m.id" class="qc-message"><strong>{{ m.id }} · {{ qcLabel(m.role) }}</strong><p>{{ m.text }}</p></div>
      <details v-for="k in previewData.knowledge" :key="k.citation.documentId+'-'+k.citation.byteStart"><summary>{{ k.rule.id }} · phiên bản {{ k.citation.revision }}</summary><blockquote>{{ k.citation.quote }}</blockquote></details>
      <v-alert v-if="!previewData.canAnalyze" type="warning" class="my-3"><strong>Chưa đủ điều kiện phân tích (chưa gửi gì cho model):</strong><ul class="ml-4"><li v-for="b in (previewData.blockers?.length ? previewData.blockers : ['UNKNOWN'])" :key="b">{{ blockerText(b) }}</li></ul></v-alert>
      <v-alert v-if="previewData.canAnalyze && previewData.resourceWarning" type="info" class="my-3">{{ blockerText(previewData.resourceWarning) }}<span v-if="previewData.freeRamGiB!=null"> RAM trống hiện tại khoảng {{ previewData.freeRamGiB }} GiB (cần ~3 GiB lần chạy đầu, ~1,5 GiB khi model đã nạp sẵn).</span></v-alert>
      <v-checkbox v-model="confirmed" :label="'Tôi đã kiểm tra bản xem trước và đồng ý gửi đúng nội dung này tới ' + destination + ' để phân tích.'" :disabled="busy || !previewData.canAnalyze" />
      <v-btn color="primary" :disabled="busy || !confirmed || !previewData.canAnalyze || !canCreate || !apiReady" @click="analyze">Gửi hội thoại đã kiểm tra để phân tích</v-btn>
    </template>
  </v-card>
</template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {qcRequest,type QcRun,type QcCitation} from '@/api/ai-quality-control';
import {qcError,qcLabel} from './presentation';
const props=withDefaults(defineProps<{permissions:string[];retentionDays:number|null;apiReady:boolean;provider?:'openai'|'ollama'}>(),{provider:'openai'});
const destination=computed(()=>props.provider==='ollama'?'model AI chạy cục bộ trên máy chủ CRM (Ollama, dữ liệu không rời máy)':'OpenAI');
const emit=defineEmits<{run:[QcRun];refresh:[]}>();
interface Preview {previewToken:string;expiresAt:string;model:string;canAnalyze:boolean;blockers?:string[];resourceWarning?:string|null;freeRamGiB?:number|null;conversation:{messages:Array<{id:string;role:string;text:string}>};knowledge:Array<{rule:{id:string};citation:QcCitation}>}
interface CrmConversationItem {id:string;title:string;kind?:'GROUP'|'USER';zaloAccount?:string|null;lastMessageAt?:string|null}
const conversations=ref<CrmConversationItem[]>([]),conversationId=ref<string|null>(null),messageLimit=ref(20),redactionsText=ref(''),previewData=ref<Preview|null>(null),confirmed=ref(false),busy=ref(false),error=ref('');
const canCreate=computed(()=>props.permissions.includes('create'));
const conversationProps=(c:CrmConversationItem)=>({title:(c.kind==='GROUP'?'👥 ':'👤 ')+c.title,subtitle:[c.kind==='GROUP'?'Nhóm':'Cá nhân',c.zaloAccount?'Nick: '+c.zaloAccount:'',c.lastMessageAt?'Tin cuối: '+new Date(c.lastMessageAt).toLocaleString('vi-VN'):''].filter(Boolean).join(' · ')});
const BLOCKERS:Record<string,string>={RETENTION_7_DAYS_REQUIRED:'Chưa đặt thời gian lưu chứng cứ 7 ngày (nút “Đặt thời gian lưu 7 ngày” hoặc tab API & cài đặt).',APPROVED_RULES_REQUIRED:'Chưa có quy tắc đã duyệt còn hiệu lực cho tổ chức: vào tab Obsidian Brain → Đồng bộ → mở quy tắc → Publish.',LOCAL_MODEL_UNAVAILABLE:'Model AI cục bộ (Ollama) chưa sẵn sàng trên máy chủ.',OPENAI_KEY_NOT_VERIFIED:'Chưa xác minh key/model OpenAI.',OPENAI_OUTBOUND_NOT_APPROVED:'Chưa được phép gửi dữ liệu ra OpenAI.',UNKNOWN:'Chưa đủ điều kiện; tải lại trang và xem trước lại.',OLLAMA_RESOURCE_LIMIT:'Máy chủ đang thiếu RAM/GPU để chạy AI. Đóng bớt ứng dụng/tab rồi bấm phân tích lại (bản xem trước vẫn còn hiệu lực trong 5 phút).',OLLAMA_RESOURCE_TELEMETRY_REQUIRED:'Bộ giám sát tài nguyên chưa chạy. Chạy script aiqc-after-reboot.ps1 trên máy chủ rồi thử lại.',OLLAMA_RESOURCE_TELEMETRY_STALE_OR_INVALID:'Bộ giám sát tài nguyên không cập nhật. Chạy script aiqc-after-reboot.ps1 trên máy chủ rồi thử lại.',OLLAMA_RESOURCE_KILL_SWITCH:'AI đang bị dừng khẩn cấp (file STOP). Xóa file STOP trên máy chủ để chạy lại.',OLLAMA_QUEUE_FULL:'AI đang bận phân tích hội thoại khác. Đợi khoảng 1 phút rồi thử lại.',OLLAMA_QUEUE_TIMEOUT:'Chờ hàng đợi AI quá lâu. Thử lại sau.',OLLAMA_CIRCUIT_OPEN:'AI vừa lỗi liên tiếp nên tạm nghỉ 30 giây. Thử lại sau.',OLLAMA_TIMEOUT:'AI phản hồi quá chậm. Thử lại với 10 tin nhắn.',OLLAMA_INVALID_OR_UNAVAILABLE:'Không gọi được model AI cục bộ (Ollama). Kiểm tra Ollama trên máy chủ.',MANUAL_PREVIEW_REQUIRED:'Bản xem trước đã hết hạn hoặc đã dùng. Bấm “Xem trước bản gửi” lại.',MANUAL_PREVIEW_CHANGED:'Hội thoại vừa có thay đổi. Bấm “Xem trước bản gửi” lại.',MANUAL_RETENTION_7_DAYS_REQUIRED:'Cần đặt thời gian lưu 7 ngày trước khi phân tích.',MANUAL_REAL_DATA_CONFIRMATION_REQUIRED:'Cần tick xác nhận trước khi phân tích.',MANUAL_REAL_TEST_NOT_AUTHORIZED:'Tài khoản/tổ chức này chưa được phép phân tích dữ liệu thật.',AI_QC_REAL_DATA_TENANT_NOT_APPROVED:'Tổ chức này chưa được phép phân tích dữ liệu thật.'};
const blockerText=(code:string)=>BLOCKERS[code]??qcError(code);
watch([conversationId,messageLimit,redactionsText],()=>{previewData.value=null;confirmed.value=false;});
async function perform(task:()=>Promise<void>){busy.value=true;error.value='';try{await task();}catch(e){const value=e as {response?:{data?:{error?:string}}};const code=value.response?.data?.error;error.value=code?blockerText(code):'Không thực hiện được. Chưa có kết quả phân tích.';}finally{busy.value=false;}}
const setRetention=()=>perform(async()=>{await qcRequest('put','/settings',{retentionDays:7});emit('refresh');});
const loadConversations=()=>perform(async()=>{conversations.value=(await qcRequest<{conversations:CrmConversationItem[]}>('get','/crm/conversations')).conversations;});
const preview=()=>perform(async()=>{confirmed.value=false;previewData.value=null;if(!conversationId.value)return;previewData.value=await qcRequest<Preview>('post','/crm/conversations/'+encodeURIComponent(conversationId.value)+'/preview',{messageLimit:messageLimit.value,redactions:redactionsText.value.split('\n').map(s=>s.trim()).filter(Boolean)});});
const analyze=()=>perform(async()=>{if(!conversationId.value||!previewData.value||!confirmed.value)return;const token=previewData.value.previewToken;confirmed.value=false;previewData.value=null;const run=await qcRequest<QcRun>('post','/crm/conversations/'+encodeURIComponent(conversationId.value)+'/analyze',{provider:props.provider,confirmRealData:true,previewToken:token});emit('run',run);});
</script>
<style scoped>.manual-heading{display:flex;gap:12px;align-items:center;margin-bottom:20px}.manual-icon{display:grid;place-items:center;width:42px;height:42px;border-radius:12px;background:#edf2ff;color:#607fdd;flex-shrink:0}.manual-heading h2{font-size:17px;font-weight:650}.manual-heading p{font-size:12px;color:var(--qc-muted);margin-top:4px}.manual-preview-meta{display:flex;align-items:center;gap:12px;font-size:12px;color:var(--qc-muted);margin:20px 0}.qc-message{padding:14px 16px;margin:10px 0;background:rgba(128,145,175,.06);border:1px solid rgba(128,145,175,.1);border-radius:10px;white-space:pre-wrap;overflow-wrap:anywhere}.qc-message strong{font-size:11px;color:var(--qc-muted)}.qc-message p{font-size:13px;line-height:1.7;margin-top:6px}blockquote{white-space:pre-wrap;padding:12px;overflow-wrap:anywhere}details{font-size:12px;padding:8px 0}summary{cursor:pointer}@media(max-width:650px){.manual-preview-meta{align-items:flex-start;flex-direction:column;gap:8px}}</style>
